// Customer Feedback Analyzer: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const POS = new Set('good great excellent love fast friendly fresh clean amazing helpful affordable nice perfect recommend quick polite'.split(' '));
const NEG = new Set('bad slow late rude expensive cold dirty poor terrible wrong never worst delayed broken overpriced stale waited'.split(' '));
const NOT = new Set(['not', 'no', 'never', "isn't", "wasn't", "didn't", "don't"]);
const THEMES = { delivery: ['delivery', 'deliver', 'rider', 'late', 'delayed', 'arrived', 'waited'], price: ['price', 'expensive', 'cheap', 'affordable', 'overpriced', 'cost'],
  quality: ['quality', 'fresh', 'stale', 'taste', 'broken', 'cold', 'food'], staff: ['staff', 'rude', 'friendly', 'polite', 'attendant', 'service'],
  'app/ordering': ['app', 'website', 'order', 'checkout', 'payment'] };
const sentiment = t => { const w = t.toLowerCase().match(/[a-z']+/g) || []; let s = 0, h = 0;
  w.forEach((x, i) => { let v = POS.has(x) ? 1 : NEG.has(x) ? -1 : 0; if (v && i && NOT.has(w[i - 1])) v = -v; if (v) { s += v; h++; } });
  return h ? s / h : 0; };
const agg = {}; let total = 0;
for (const r of input) {
  const s = sentiment(r.comment); total += s;
  for (const [th, ws] of Object.entries(THEMES)) if (ws.some(w => r.comment.toLowerCase().includes(w))) {
    agg[th] = agg[th] || { n: 0, s: 0, quotes: [] }; agg[th].n++; agg[th].s += s; if (s < 0) agg[th].quotes.push(r.comment); }
}
const ranked = Object.entries(agg).map(([t, v]) => ({ theme: t, mentions: v.n, avg: Math.round(v.s / v.n * 100) / 100,
  impact: Math.round(v.n * Math.max(0, -v.s / v.n) * 100) / 100, quote: v.quotes[0] || '' })).sort((a, b) => b.impact - a.impact);
const report = `Comments: ${input.length}, overall sentiment ${(total / input.length).toFixed(2)} (-1 to +1)\n\nFix first:\n` +
  ranked.map(r => `- ${r.theme}: ${r.mentions} mentions, sentiment ${r.avg}${r.quote ? ` - "${r.quote}"` : ''}`).join('\n');
return [{ json: { top_issue: ranked[0] && ranked[0].theme, report, themes: ranked } }];
